# region: fold
def fold(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.isdigit() and int(s) > 0:
            out.append(int(s))
    return out

# region: gather
def gather(xs, floor_=2):
    return [v for v in xs if v >= floor_]

# region: shape
def shape(xs):
    return [v for v in xs if v % 2 == 0]

# region: render
def render(xs):
    return {'n': len(xs), 'total': max(xs)}

# region: intake
def intake(summary, bar=4):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) >= bar else 'low'
    return out

# region: run
def run(raw):
    return intake(render(shape(gather(fold(raw)))))

